import urllib.request, json, re

def imgs(title):
    url = f"https://en.wikipedia.org/w/api.php?action=query&titles={urllib.parse.quote(title)}&prop=images&imlimit=100&format=json"
    req = urllib.request.Request(url, headers={'User-Agent':'research/1.0'})
    d = json.loads(urllib.request.urlopen(req, timeout=20).read())
    page = list(d['query']['pages'].values())[0]
    return [i['title'] for i in page.get('images',[])]

import urllib.parse
for t in ["Side to Side", "All About That Bass"]:
    print(t, ":")
    for i in imgs(t):
        if any(k in i.lower() for k in ['screenshot','still','grande','trainor','video']):
            print("   ", i)
EOF"}

