import urllib.request, re, json, urllib.parse

def ddg_images(q, n=25):
    s = urllib.request.urlopen(urllib.request.Request("https://duckduckgo.com/?q="+urllib.parse.quote(q), headers={'User-Agent':'Mozilla/5.0'}), timeout=20).read().decode('utf-8','ignore')
    m = re.search(r'vqd=([\d-]+)', s) or re.search(r"vqd='([\d-]+)'", s) or re.search(r'vqd="([\d-]+)"', s)
    if not m:
        m2 = re.search(r"vqd=([\w-]+)&", s)
        vqd = m2.group(1) if m2 else None
    else:
        vqd = m.group(1)
    if not vqd:
        print("no vqd"); return []
    url = f"https://duckduckgo.com/i.js?l=us-en&o=json&q={urllib.parse.quote(q)}&vqd={vqd}&f=,,,&p=1"
    d = json.loads(urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0','Referer':'https://duckduckgo.com/'}), timeout=20).read())
    return d.get('results', [])

res = ddg_images('Ariana Grande "Side to Side" music video still pink leotard spin class')
print("results:", len(res))
for r in res[:25]:
    print(r.get('width'),'x',r.get('height'),'|', r.get('title','')[:60],'|', r.get('image','')[:120])
